using System;using System.Reflection;using Game.Components;using Unity.Entities;using System.IO;using System.Threading;using Unity.Jobs;using Unity.Collections;using Unity.Mathematics;using Newtonsoft.Json.Linq;
namespace Game.Runtime{internal static class SelectedPathSchedulingControls{
 public static int Main(string[] args){if(args.Length==1)return Run(args[0]);if(args.Length==3&&args[0]=="--surface")return SelectedPathSurfaceEquality.Run(new[]{args[1],args[2]});throw new ArgumentException("Result path, or --surface pinned-input.json result.json required");}

 static int checks;static int actualFixtureEntityCount;static int synchronousFallbackCount;public struct OtherBoundedJob:IJobFor{public void Execute(int index){synchronousFallbackCount+=index+1;}}static void Check(bool yes,string name){if(!yes)throw new InvalidOperationException(name);checks++;}
 static void Set(object box,string name,object value){typeof(UnitPathfindingSystem).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(box,value);}
 static object Get(object box,string name)=>typeof(UnitPathfindingSystem).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(box);
 static void RealOwnerFaultCleanup(){
 var expected=new InvalidOperationException("real owner pending-worker sentinel");var handle=OwnedJobBackend.StartSelectedPath(()=>throw expected,default);var stream=new NativeStream(1,Allocator.Persistent);var alias=stream;
 var em=new EntityManager();var diagnosticsEntity=new Entity{Index=1,Version=1};var pendingEntity=new Entity{Index=2,Version=1};em.ImportEntity(diagnosticsEntity);em.AddComponentData(diagnosticsEntity,new UnitPathfindingDiagnosticLogQueueComponent());em.AddBuffer<UnitPathfindingDiagnosticLogComponent>(diagnosticsEntity);em.ImportEntity(pendingEntity);em.AddComponentData(pendingEntity,new UnitPathfindingPendingStateComponent());var state=new SystemState{EntityManager=em,Enabled=true};var initializedOwner=default(UnitPathfindingSystem);state.Begin();initializedOwner.OnCreate(ref state);state.End();object box=initializedOwner;Set(box,"_hasPendingPathJob",true);Set(box,"_pendingPathHandle",handle);Set(box,"_pendingPathStream",stream);Set(box,"_pendingRequestCount",1);
 var grid=new UnitPathGridSnapshot{Walkable=new NativeArray<GridWalkable>(1,Allocator.Persistent)};Set(box,"_gridSnapshot",grid);
 var owner=(UnitPathfindingSystem)box;Exception actual=null;state.Begin();try{owner.OnDestroy(ref state);}catch(Exception e){actual=e;}
 Check(ReferenceEquals(actual,expected),"REAL OnDestroy preserves first worker exception");Check(handle.IsCompleted,"REAL OnDestroy joined faulted worker");Check(!alias.IsCreated,"REAL DisposePending removed stream after fault join");box=owner;Check(!(bool)Get(box,"_hasPendingPathJob"),"REAL DisposeCompleted reset pending flag despite worker fault");Check(!((UnitPathGridSnapshot)Get(box,"_gridSnapshot")).Walkable.IsCreated,"REAL OnDestroy disposed/reset grid snapshot despite worker fault");owner.OnDestroy(ref state);Check(true,"REAL repeated OnDestroy safe after prior failure");actualFixtureEntityCount=em.CreateEntityQuery(new EntityQueryDesc{Options=EntityQueryOptions.IncludePrefab|EntityQueryOptions.IncludeDisabledEntities|EntityQueryOptions.IncludeSystems|EntityQueryOptions.IncludeMetaChunks}).CalculateEntityCount();
 Exception first=expected;var secondary=new ArgumentException("secondary cleanup sentinel");int before=OwnedJobBackend.SecondaryCleanupFailureCount;OwnedJobBackend.PreserveCleanupFailure(ref first,secondary);Check(ReferenceEquals(first,expected)&&ReferenceEquals(OwnedJobBackend.SecondaryCleanupFailures[before],secondary),"preallocated secondary retention preserves first error");
 }
 internal static int Run(string output){
 using var gate=new ManualResetEventSlim(false);using var entered=new ManualResetEventSlim(false);int phase=0;int main=Thread.CurrentThread.ManagedThreadId,worker=main;
 var a=OwnedJobBackend.StartSelectedPath(()=>{worker=Thread.CurrentThread.ManagedThreadId;entered.Set();if(!gate.Wait(5000))throw new TimeoutException();phase=1;},default);
 Check(entered.Wait(5000),"worker entered without Complete");Check(!a.IsCompleted,"pending status");Check(!a.IsCompleted,"status query has no execution effect");Check(worker!=main,"body executes off scheduling thread");var copy=a;int dependent=0;var b=OwnedJobBackend.StartSelectedPath(()=>{if(phase!=1)throw new Exception("dependency publication");dependent=1;},a);Check(dependent==0,"dependency blocks body");gate.Set();copy.Complete();a.Complete();b.Complete();Check(a.IsCompleted&&phase==1&&dependent==1,"copy/repeat Complete joins and publishes");Check(default(JobHandle).IsCompleted,"default complete");
 var expected=new ArgumentException("actual worker sentinel");var bad=OwnedJobBackend.StartSelectedPath(()=>throw expected,default);Exception seen=null;try{bad.Complete();}catch(Exception e){seen=e;}Check(ReferenceEquals(seen,expected),"worker exception identity");seen=null;try{bad.Complete();}catch(Exception e){seen=e;}Check(ReferenceEquals(seen,expected),"repeat preserves same worker error");int forbidden=0;var blocked=OwnedJobBackend.StartSelectedPath(()=>forbidden++,bad);try{blocked.Complete();}catch(Exception e){Check(ReferenceEquals(e,expected),"dependency failure retained");}Check(forbidden==0,"failed dependency never executes body");
 using var otherGate=new ManualResetEventSlim(false);var other=OwnedJobBackend.StartSelectedPath(()=>{if(!otherGate.Wait(5000))throw new TimeoutException();},default);var combined=JobHandle.CombineDependencies(bad,other,default);ThreadPool.QueueUserWorkItem(_=>otherGate.Set());try{combined.Complete();}catch(Exception e){Check(ReferenceEquals(e,expected),"combine keeps first failure");}Check(other.IsCompleted,"combine joins all children despite first fault");
 var stream=new NativeStream(1,Allocator.Persistent);var writer=stream.AsWriter();var streamJob=OwnedJobBackend.StartSelectedPath(()=>{writer.BeginForEachIndex(0);writer.Write(new int2(7,9));writer.EndForEachIndex();},default);streamJob.Complete();var reader=stream.AsReader();Check(reader.BeginForEachIndex(0)==1&&reader.Read<int2>().x==7,"stream published after join");reader.EndForEachIndex();stream.Dispose();using(var next=new NativeStream(1,Allocator.Persistent))Check(next.IsCreated,"next stream created only after join and dispose");
 new OtherBoundedJob().Schedule(3,default(JobHandle)).Complete();Check(synchronousFallbackCount==6,"nonselected bounded IJobFor retains ORIGINAL synchronous fallback");RealOwnerFaultCleanup();int originalPathCases=SelectedPathOriginalEquality.Run();Check(originalPathCases==140,"actualoriginal/direct/deferred140 fullpaths andALLscratch exact");
 var result=new JObject{["checks"]=checks,["world"]=false,["actual_fixture_entity_count"]=actualFixtureEntityCount,["entity_manager_created"]=true,["world_scope"]="Finite actual EntityManager shim/originalOnCreate, no AutonomousWorld/nativeWorld/mission initialization",["secondary_cleanup_failures"]=OwnedJobBackend.SecondaryCleanupFailureCount,["original_path_cases"]=originalPathCases,["secondary_recording_failed"]=OwnedJobBackend.SecondaryCleanupRecordingFailed,["scope"]="Actual selected-backend primitive+real original OnDestroy fault teardown+original140 noSurface fullpath andALLscratch controls; no mission/native timing parity"};File.WriteAllText(output,result.ToString());Console.WriteLine("[SelectedPathSchedulingControls] result=Passed checks="+checks+" world=False");return 0;
 }
